<script setup>
import { computed, ref } from 'vue'
import { usePlatformStore } from '@/stores/platform'
const store=usePlatformStore();const module=ref('');const keyword=ref('');const rows=computed(()=>store.auditLogs.filter(x=>(!module.value||x.module===module.value)&&(!keyword.value||`${x.user}${x.action}`.toLowerCase().includes(keyword.value.toLowerCase()))))
</script>
<template><div class="farmer-page"><div class="page-head"><div><h1 class="page-title">关键操作日志</h1><p class="page-subtitle">审计登录、阈值修改、设备绑定、远程控制和账号状态变更。</p></div><div class="page-actions"><el-input v-model="keyword" clearable placeholder="搜索用户或操作" :disabled="!store.capabilities.auditLogs"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-select v-model="module" clearable placeholder="全部模块" :disabled="!store.capabilities.auditLogs"><el-option v-for="item in ['远程控制','阈值配置','设备管理','设备绑定','用户管理','系统参数','全局告警']" :key="item" :label="item" :value="item"/></el-select></div></div><el-alert v-if="!store.capabilities.auditLogs" title="当前数据库未定义审计日志表" description="为避免把临时前端记录误当作真实审计数据，正式接口模式下暂不展示日志；请后端补充 audit_log 表和查询接口。" type="warning" show-icon :closable="false" class="schema-warning"/><section class="content-panel"><el-table :data="rows" class="compact-table"><el-table-column prop="time" label="时间" min-width="170"/><el-table-column prop="user" label="操作用户" min-width="140"/><el-table-column prop="module" label="模块" width="110"><template #default="scope"><span class="status-pill info">{{scope.row.module}}</span></template></el-table-column><el-table-column prop="action" label="操作内容" min-width="320"/><el-table-column prop="result" label="结果" width="90"/><el-table-column prop="ip" label="IP地址" min-width="130"/></el-table></section></div></template>
